import React, { useState } from "react";

const OrarSecretariat = () => {
    const [schedule, setSchedule] = useState([]);
    const [newEntry, setNewEntry] = useState({ day: "", time: "", activity: "" });
    const [editIndex, setEditIndex] = useState(null); // Indexul intrării care este editată
    const [editEntry, setEditEntry] = useState({ day: "", time: "", activity: "" }); // Intrarea curentă pentru editare

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setNewEntry({ ...newEntry, [name]: value });
    };

    const handleAddEntry = (e) => {
        e.preventDefault();
        setSchedule([...schedule, newEntry]);
        setNewEntry({ day: "", time: "", activity: "" });
    };

    const handleEditClick = (index) => {
        setEditIndex(index); // Setează indexul intrării care este editată
        setEditEntry(schedule[index]); // Preia datele intrării pentru editare
    };

    const handleEditInputChange = (e) => {
        const { name, value } = e.target;
        setEditEntry({ ...editEntry, [name]: value });
    };

    const handleSaveEdit = () => {
        const updatedSchedule = [...schedule];
        updatedSchedule[editIndex] = editEntry; // Actualizează intrarea editată
        setSchedule(updatedSchedule);
        setEditIndex(null); // Resetează indexul de editare
        setEditEntry({ day: "", time: "", activity: "" });
    };

    const handleCancelEdit = () => {
        setEditIndex(null); // Anulează editarea
        setEditEntry({ day: "", time: "", activity: "" });
    };

    return (
        <div>
            <h2>Modificare Orar</h2>
            <form onSubmit={handleAddEntry}>
                <label>
                    Ziua:
                    <input
                        type="text"
                        name="day"
                        value={newEntry.day}
                        onChange={handleInputChange}
                        placeholder="Introdu ziua"
                    />
                </label>
                <br />
                <label>
                    Ora:
                    <input
                        type="text"
                        name="time"
                        value={newEntry.time}
                        onChange={handleInputChange}
                        placeholder="Introdu ora"
                    />
                </label>
                <br />
                <label>
                    Activitate:
                    <input
                        type="text"
                        name="activity"
                        value={newEntry.activity}
                        onChange={handleInputChange}
                        placeholder="Introdu activitatea"
                    />
                </label>
                <br />
                <button type="submit">Adaugă</button>
            </form>

            <h3>Orar Curent</h3>
            <ul>
                {schedule.map((entry, index) => (
                    <li key={index}>
                        {editIndex === index ? (
                            <div>
                                <input
                                    type="text"
                                    name="day"
                                    value={editEntry.day}
                                    onChange={handleEditInputChange}
                                    placeholder="Ziua"
                                />
                                <input
                                    type="text"
                                    name="time"
                                    value={editEntry.time}
                                    onChange={handleEditInputChange}
                                    placeholder="Ora"
                                />
                                <input
                                    type="text"
                                    name="activity"
                                    value={editEntry.activity}
                                    onChange={handleEditInputChange}
                                    placeholder="Activitatea"
                                />
                                <button onClick={handleSaveEdit}>Salvează</button>
                                <button onClick={handleCancelEdit}>Anulează</button>
                            </div>
                        ) : (
                            <div>
                                {entry.day}, {entry.time} - {entry.activity}
                                <button onClick={() => handleEditClick(index)}>Edit</button>
                            </div>
                        )}
                    </li>
                ))}
            </ul>
        </div>
    );
};

export default OrarSecretariat;
